const projects = $input.all().map(i => i.json);
const today = new Date();

const active = projects.filter(p => p.status === 'active');
const totalValue = active.reduce((sum, p) => sum + (p.value_eur || 0), 0);

const rows = active.map(p => {
  const deadline = p.deadline ? new Date(p.deadline) : null;
  const daysLeft = deadline ? Math.ceil((deadline - today) / (1000 * 60 * 60 * 24)) : null;
  const urgency = daysLeft === null ? '—' : daysLeft <= 7 ? '🔴' : daysLeft <= 14 ? '🟡' : '🟢';
  return `${urgency} *${p.name}* — ${p.customer || 'Unknown'}\n   Deadline: ${p.deadline || 'TBD'} ${daysLeft !== null ? '(' + daysLeft + 'd)' : ''} | Value: ${p.value_eur ? '€' + (p.value_eur/1e6).toFixed(1) + 'M' : 'TBD'}`;
}).join('\n\n');

const week = Math.ceil((today - new Date(today.getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));

const slackMessage = `📊 *Loonar Weekly Pipeline Report — W${week}*\n\n*${active.length} active bid${active.length !== 1 ? 's' : ''}* | Total pipeline: *€${(totalValue/1e6).toFixed(1)}M*\n\n${rows || '_No active projects_'}\n\n_Generated ${today.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}_`;

const emailHtml = `
<h2 style="color:#1a3a5c">Loonar Weekly Pipeline Report — W${week}</h2>
<p><strong>${active.length} active bids</strong> | Total pipeline: <strong>€${(totalValue/1e6).toFixed(1)}M</strong></p>
<table style="width:100%;border-collapse:collapse;font-family:sans-serif;font-size:14px">
  <thead>
    <tr style="background:#1a3a5c;color:white">
      <th style="padding:8px;text-align:left">Project</th>
      <th style="padding:8px;text-align:left">Customer</th>
      <th style="padding:8px;text-align:left">Deadline</th>
      <th style="padding:8px;text-align:left">Days Left</th>
      <th style="padding:8px;text-align:right">Value</th>
    </tr>
  </thead>
  <tbody>
    ${active.map((p, i) => {
      const deadline = p.deadline ? new Date(p.deadline) : null;
      const daysLeft = deadline ? Math.ceil((deadline - today) / (1000 * 60 * 60 * 24)) : null;
      const bg = i % 2 === 0 ? '#f8fafc' : '#ffffff';
      const urgencyColor = daysLeft === null ? '' : daysLeft <= 7 ? 'color:#dc2626' : daysLeft <= 14 ? 'color:#d97706' : 'color:#16a34a';
      return `<tr style="background:${bg}"><td style="padding:8px">${p.name}</td><td style="padding:8px">${p.customer || '—'}</td><td style="padding:8px">${p.deadline || 'TBD'}</td><td style="padding:8px;${urgencyColor}">${daysLeft !== null ? daysLeft + 'd' : '—'}</td><td style="padding:8px;text-align:right">${p.value_eur ? '€' + (p.value_eur/1e6).toFixed(1) + 'M' : 'TBD'}</td></tr>`;
    }).join('')}
  </tbody>
</table>
<p style="color:#6b7280;font-size:12px">Generated ${today.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
`;

return [{ json: { slackMessage, emailHtml, activeCount: active.length, totalValue, week } }];

// In production: send to Slack channel / email distribution list
// For now: log the report
const report = $input.first().json;
console.log('=== WEEKLY PIPELINE REPORT ===');
console.log(report.slackMessage);
console.log('==============================');
return [{ json: { status: 'report_sent', week: report.week, activeProjects: report.activeCount, pipelineEur: report.totalValue } }];
